-- ─────────────────────────────────────────────────────────────────────────────
-- 20261123120000 — M9b2a: membership IDs stored as plaintext (owner decisions
-- A1, D1, D2, D5 of 2026-11-23; supersedes the HMAC + AES-GCM storage of
-- 20261123100100)
--
-- Owner decision A1: the original membership ID (e.g. UAL/K7P9Q) is stored as
-- plaintext. It is NOT hashed and NOT encrypted. The random suffix is still
-- generated by the web server (crypto.randomInt). Access is restricted instead:
-- the table has RLS with no policies, and only security-definer functions read
-- it, each re-checking permission.
--
-- What this migration does (it is safe to apply before the backfill):
--
--   1. membership_ids gains:
--        · membership_id  text — the original ID, as issued
--        · canonical_id   text — what a person's typing is compared with:
--                                upper-case, no spaces or separators, O→0,
--                                I/L→1 (app.canonical_membership_id; the same
--                                rule as apps/web/lib/membership-id.ts)
--      Both are unique per community over ALL rows, revoked included, so a
--      revoked or replaced ID is never issued again (owner decision D2).
--      Revoking or replacing an ID no longer erases anything.
--   2. id_hash becomes nullable. From now on it is used ONLY for the two legacy
--      rows whose plaintext cannot be recovered (owner decision D1). New rows
--      never get a hash or a ciphertext.
--   3. Issue / rotate take the plaintext ID. While a community still holds a
--      legacy fingerprint-only row, the server must also pass the candidate's
--      HMAC (p_legacy_fingerprint) so the old fingerprints stay reserved; if it
--      cannot (secret missing), issuing in that community is refused. This
--      fails closed.
--   4. get_member_membership_id returns the plaintext ID and requires
--      membership.issue_ids (owner decision D5). member.view_contact alone no
--      longer reveals a full ID; the masked summary still uses view_contact.
--   5. validate_membership_id takes the typed ID, canonicalises it in SQL and
--      compares it with canonical_id. Same rate limits, same generic answer.
--   6. A one-time, narrowly gated backfill function for the existing live rows
--      (app.backfill_membership_id_plaintext), callable only by the table
--      owner. The web server decrypts with the itest secret and calls it from
--      scripts/itest/membership-id-plaintext-backfill.mjs.
--
-- Not done here (20261123120100, after the backfill is verified and approved):
-- drop id_ciphertext and key_version, clear id_hash on rows that now hold
-- plaintext, require every live row to hold plaintext, and drop the backfill
-- function.
--
-- No plaintext ID is ever written to an audit row, an exception message or a
-- notice by any function below. Audit rows keep the masked form.
--
-- Existing rows: none change in this migration. Financial effect: none.
--
-- ROLLBACK (itest only; before 20261123120100 is applied, nothing is lost):
--   drop the functions created below; re-run the issue / rotate / revoke /
--   get / validate / insert / guard definitions from 20261123100100 (they
--   still work, because id_hash and id_ciphertext are still on every
--   pre-existing row); drop index membership_ids_community_canonical_key and
--   membership_ids_community_plaintext_key; drop constraints
--   membership_ids_storage_shape, membership_ids_plaintext_format,
--   membership_ids_canonical_matches; restore membership_ids_live_has_ciphertext
--   and `id_hash set not null` (valid only if no plaintext-only row was issued
--   meanwhile; otherwise those rows must be re-hashed and re-encrypted by the
--   server first); drop columns membership_id and canonical_id; drop function
--   app.canonical_membership_id.
-- ─────────────────────────────────────────────────────────────────────────────


-- ══ 1. Canonical form ════════════════════════════════════════════════════════

create or replace function app.canonical_membership_id(p_raw text)
returns text
language sql
immutable
parallel safe
set search_path = ''
as $$
  select translate(regexp_replace(upper(coalesce(p_raw, '')), '[[:space:]/_.-]+', '', 'g'), 'OIL', '011');
$$;

comment on function app.canonical_membership_id(text) is
  'M9b2a: the comparison form of a membership ID — upper-case, spaces and / - _ . removed, O→0, I/L→1. Mirrors canonicalMembershipId() in apps/web/lib/membership-id.ts.';

revoke all on function app.canonical_membership_id(text) from public, anon, authenticated;


-- ══ 2. Columns and constraints ═══════════════════════════════════════════════

alter table public.membership_ids
  add column if not exists membership_id text,
  add column if not exists canonical_id  text;

alter table public.membership_ids alter column id_hash drop not null;

-- The 20261123100100 rule "a live row has a ciphertext" no longer holds: new
-- rows have none.
alter table public.membership_ids drop constraint if exists membership_ids_live_has_ciphertext;

-- Either a plaintext row (both new columns), or a legacy fingerprint-only row
-- (no plaintext, a hash). Nothing else.
alter table public.membership_ids
  add constraint membership_ids_storage_shape check (
    (membership_id is not null and canonical_id is not null)
    or (membership_id is null and canonical_id is null and id_hash is not null)
  );

alter table public.membership_ids
  add constraint membership_ids_plaintext_format check (
    membership_id is null or (
      membership_id ~ '^[A-Z][A-Z0-9]{1,9}[/-][0-9A-HJKMNP-TV-Z]{5,8}$'
      and left(membership_id, char_length(prefix) + 1) = prefix || separator
      and right(membership_id, 2) = last2
    )
  );

alter table public.membership_ids
  add constraint membership_ids_canonical_matches check (
    canonical_id is null or canonical_id = app.canonical_membership_id(membership_id)
  );

-- Unique within the community across ALL rows, revoked included (D2).
create unique index membership_ids_community_canonical_key
  on public.membership_ids (community_id, canonical_id) where canonical_id is not null;
create unique index membership_ids_community_plaintext_key
  on public.membership_ids (community_id, membership_id) where membership_id is not null;

comment on table public.membership_ids is
  'F4.4 / M9b2a: a member''s membership ID, stored as plaintext (owner decision A1, 2026-11-23). RLS on, no policies: read only through security-definer functions that check permission. Revoked and replaced rows keep their ID so it is never reissued (D2). Two legacy itest rows hold only an HMAC fingerprint (D1).';
comment on column public.membership_ids.membership_id is
  'The original membership ID as issued (e.g. UAL/K7P9Q). Plaintext by owner decision A1. Never copied into audit rows, logs or queue payloads.';
comment on column public.membership_ids.canonical_id is
  'app.canonical_membership_id(membership_id): what typed input is compared with. Unique per community over all rows.';
comment on column public.membership_ids.id_hash is
  'LEGACY (20261123100100). Kept only on rows whose plaintext could not be recovered, as a permanently reserved fingerprint (owner decision D1). New rows: null.';
comment on column public.membership_ids.id_ciphertext is
  'LEGACY (20261123100100). Read only by the one-time backfill; dropped by 20261123120100.';


-- ══ 3. Row guard ═════════════════════════════════════════════════════════════

create or replace function app.guard_membership_id_row()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if not exists (select 1 from public.members m where m.id = new.member_id and m.community_id = new.community_id) then
      raise exception 'MEMBER_COMMUNITY_MISMATCH' using errcode = 'P0001';
    end if;
    -- New rows are plaintext rows only (A1). No new hash or ciphertext.
    if new.membership_id is null or new.id_hash is not null or new.id_ciphertext is not null then
      raise exception 'PLAINTEXT_ONLY: a new membership ID row holds the plaintext ID and nothing else' using errcode = 'P0001';
    end if;
    return new;
  end if;

  -- Fields that never move, whatever the update.
  if new.member_id <> old.member_id or new.community_id <> old.community_id
     or new.issued_at <> old.issued_at or new.last2 <> old.last2 or new.prefix <> old.prefix
     or new.separator <> old.separator or new.key_version <> old.key_version
     or new.id_hash is distinct from old.id_hash
     or new.id_ciphertext is distinct from old.id_ciphertext then
    raise exception 'MEMBERSHIP_ID_IS_IMMUTABLE: a membership ID can only be revoked, once' using errcode = 'P0001';
  end if;

  -- One-time backfill (M9b2a): a live legacy row gains its plaintext. Only
  -- inside app.backfill_membership_id_plaintext, which sets the flag.
  if old.membership_id is null and new.membership_id is not null then
    if coalesce(current_setting('app.membership_id_backfill', true), '') <> 'on'
       or old.revoked_at is not null or new.revoked_at is not null then
      raise exception 'MEMBERSHIP_ID_IS_IMMUTABLE: a membership ID can only be revoked, once' using errcode = 'P0001';
    end if;
    return new;
  end if;

  -- Otherwise: only revocation, once. The ID itself is KEPT (D2).
  if old.revoked_at is not null
     or new.revoked_at is null
     or new.membership_id is distinct from old.membership_id
     or new.canonical_id is distinct from old.canonical_id then
    raise exception 'MEMBERSHIP_ID_IS_IMMUTABLE: a membership ID can only be revoked, once' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
revoke execute on function app.guard_membership_id_row() from public, anon, authenticated;


-- ══ 4. Issue / rotate / revoke ═══════════════════════════════════════════════

drop function if exists app.issue_membership_id(uuid, bytea, text, text, smallint, text, text);
drop function if exists app.rotate_membership_id(uuid, bytea, text, text, smallint, text, text, text);
drop function if exists app.insert_membership_id(public.members, bytea, text, text, smallint, text, text);

-- Shared by issue and rotate: checks, then inserts one live plaintext row.
-- Not granted. Never puts p_membership_id into a message.
create or replace function app.insert_membership_id(
  p_member             public.members,
  p_membership_id      text,
  p_legacy_fingerprint bytea
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_settings   public.community_membership_id_settings%rowtype;
  v_suffix     text;
  v_id         uuid;
  v_constraint text;
begin
  select * into v_settings from public.community_membership_id_settings where community_id = p_member.community_id;
  if v_settings.community_id is null or not v_settings.enabled then
    raise exception 'MEMBERSHIP_IDS_OFF: turn on membership IDs in community settings first' using errcode = 'P0001';
  end if;
  if not app.member_in_good_standing(p_member.status) then
    raise exception 'MEMBER_NOT_ELIGIBLE: a % member cannot hold a membership ID', p_member.status using errcode = 'P0001';
  end if;
  if p_membership_id is null or char_length(p_membership_id) > 40 then
    raise exception 'INVALID_INPUT: membership ID is missing' using errcode = '22023';
  end if;

  -- The server generated the ID from the settings it read; if they changed in
  -- between, refuse rather than issue an ID in a superseded format.
  if left(p_membership_id, char_length(v_settings.prefix) + 1) <> v_settings.prefix || v_settings.separator then
    raise exception 'SETTINGS_CHANGED: the membership ID format changed; try again' using errcode = 'P0001';
  end if;
  v_suffix := substr(p_membership_id, char_length(v_settings.prefix) + 2);
  if char_length(v_suffix) <> v_settings.suffix_length then
    raise exception 'SETTINGS_CHANGED: the membership ID format changed; try again' using errcode = 'P0001';
  end if;
  if v_suffix !~ '^[0-9A-HJKMNP-TV-Z]+$' or v_suffix !~ '[A-Z]' then
    raise exception 'INVALID_INPUT: the random part of a membership ID is not in the expected alphabet' using errcode = '22023';
  end if;

  -- Legacy fingerprints stay reserved forever (owner decision D1).
  if exists (select 1 from public.membership_ids mi
             where mi.community_id = p_member.community_id and mi.membership_id is null) then
    if p_legacy_fingerprint is null or octet_length(p_legacy_fingerprint) <> 32 then
      raise exception 'LEGACY_CHECK_UNAVAILABLE: this community has reserved legacy IDs and the server cannot check against them' using errcode = 'P0001';
    end if;
    if exists (select 1 from public.membership_ids mi
               where mi.community_id = p_member.community_id and mi.id_hash = p_legacy_fingerprint) then
      raise exception 'MEMBERSHIP_ID_COLLISION' using errcode = 'P0001';
    end if;
  end if;

  begin
    insert into public.membership_ids
      (community_id, member_id, membership_id, canonical_id, prefix, separator, last2, issued_by)
    values
      (p_member.community_id, p_member.id, p_membership_id, app.canonical_membership_id(p_membership_id),
       v_settings.prefix, v_settings.separator, right(p_membership_id, 2), auth.uid())
    returning id into v_id;
  exception when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    if v_constraint in ('membership_ids_community_canonical_key', 'membership_ids_community_plaintext_key') then
      -- The server regenerates the random suffix and calls again.
      raise exception 'MEMBERSHIP_ID_COLLISION' using errcode = 'P0001';
    end if;
    raise exception 'ALREADY_ISSUED: this member already has a membership ID' using errcode = 'P0001';
  end;
  return v_id;
end;
$$;
revoke execute on function app.insert_membership_id(public.members, text, bytea) from public, anon, authenticated;

create or replace function app.issue_membership_id(
  p_member_id          uuid,
  p_membership_id      text,
  p_legacy_fingerprint bytea default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_member public.members%rowtype;
  v_id     uuid;
  v_masked text;
begin
  select * into v_member from public.members where id = p_member_id for update;
  if v_member.id is null then
    raise exception 'NOT_FOUND: member' using errcode = 'P0002';
  end if;
  perform app.require_permission(v_member.community_id, 'membership.issue_ids');

  v_id := app.insert_membership_id(v_member, p_membership_id, p_legacy_fingerprint);

  select mi.prefix || mi.separator || '…' || mi.last2 into v_masked from public.membership_ids mi where mi.id = v_id;
  perform app.write_audit_log(
    v_member.community_id, 'officer', auth.uid(), 'member.issue_membership_id', 'member', p_member_id,
    null, jsonb_build_object('membership_id_id', v_id, 'masked', v_masked)
  );
  return v_id;
end;
$$;

comment on function app.issue_membership_id(uuid, text, bytea) is
  'F4.5 / M9b2a. membership.issue_ids: records a server-generated membership ID (plaintext, owner decision A1) for a member in good standing who has none. MEMBERSHIP_ID_COLLISION = regenerate and call again. p_legacy_fingerprint is required only in a community holding legacy fingerprint-only rows (D1). Audited with the masked form only.';

create or replace function app.rotate_membership_id(
  p_member_id          uuid,
  p_membership_id      text,
  p_reason             text,
  p_legacy_fingerprint bytea default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_member public.members%rowtype;
  v_old    public.membership_ids%rowtype;
  v_id     uuid;
  v_masked text;
begin
  select * into v_member from public.members where id = p_member_id for update;
  if v_member.id is null then
    raise exception 'NOT_FOUND: member' using errcode = 'P0002';
  end if;
  perform app.require_permission(v_member.community_id, 'membership.issue_ids');

  select * into v_old from public.membership_ids where member_id = p_member_id and revoked_at is null for update;
  if v_old.id is null then
    raise exception 'NOTHING_TO_REPLACE: this member has no membership ID yet' using errcode = 'P0001';
  end if;

  -- The old ID is revoked and KEPT, so it is never issued again (D2).
  update public.membership_ids
  set revoked_at = now(), revoked_by = auth.uid(),
      revoke_reason = coalesce(nullif(trim(p_reason), ''), 'replaced')
  where id = v_old.id;

  v_id := app.insert_membership_id(v_member, p_membership_id, p_legacy_fingerprint);

  -- Grants issued under the old ID stop working at once.
  update public.membership_access_grants set revoked_at = now()
  where membership_id_id = v_old.id and revoked_at is null;

  select mi.prefix || mi.separator || '…' || mi.last2 into v_masked from public.membership_ids mi where mi.id = v_id;
  perform app.write_audit_log(
    v_member.community_id, 'officer', auth.uid(), 'member.rotate_membership_id', 'member', p_member_id,
    jsonb_build_object('membership_id_id', v_old.id, 'masked', v_old.prefix || v_old.separator || '…' || v_old.last2),
    jsonb_build_object('membership_id_id', v_id, 'masked', v_masked),
    nullif(trim(p_reason), '')
  );
  return v_id;
end;
$$;

comment on function app.rotate_membership_id(uuid, text, text, bytea) is
  'F4.7 / M9b2a. membership.issue_ids: in one transaction revokes the member''s current ID (kept, so it is never reissued — D2), records the new one, and revokes access grants made with the old one. Audited with masked forms only.';

create or replace function app.revoke_membership_id(p_member_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_member public.members%rowtype;
  v_old    public.membership_ids%rowtype;
begin
  select * into v_member from public.members where id = p_member_id for update;
  if v_member.id is null then
    raise exception 'NOT_FOUND: member' using errcode = 'P0002';
  end if;
  perform app.require_permission(v_member.community_id, 'membership.issue_ids');
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'REASON_REQUIRED: say why the membership ID is being revoked' using errcode = '22023';
  end if;

  select * into v_old from public.membership_ids where member_id = p_member_id and revoked_at is null for update;
  if v_old.id is null then
    raise exception 'NOTHING_TO_REVOKE: this member has no membership ID' using errcode = 'P0001';
  end if;

  -- Revoked and KEPT (D2).
  update public.membership_ids
  set revoked_at = now(), revoked_by = auth.uid(), revoke_reason = trim(p_reason)
  where id = v_old.id;
  update public.membership_access_grants set revoked_at = now()
  where membership_id_id = v_old.id and revoked_at is null;

  perform app.write_audit_log(
    v_member.community_id, 'officer', auth.uid(), 'member.revoke_membership_id', 'member', p_member_id,
    jsonb_build_object('membership_id_id', v_old.id, 'masked', v_old.prefix || v_old.separator || '…' || v_old.last2),
    null, trim(p_reason)
  );
end;
$$;


-- ══ 5. Reading the full ID (D5) ══════════════════════════════════════════════

drop function if exists app.get_member_membership_id(uuid);

-- The member's current ID, in full. Owner decision D5: the owner and officers
-- holding membership.issue_ids (by role or by grant) only — member.view_contact
-- alone is not enough. membership_id is null for a live legacy row that has
-- not been backfilled yet (the UI then shows the masked form).
create or replace function app.get_member_membership_id(p_member_id uuid)
returns table (
  membership_id_id uuid,
  membership_id    text,
  prefix           text,
  separator        text,
  last2            text,
  issued_at        timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_community uuid;
begin
  select community_id into v_community from public.members where id = p_member_id;
  if v_community is null then
    return;
  end if;
  perform app.require_permission(v_community, 'membership.issue_ids');
  return query
  select mi.id, mi.membership_id, mi.prefix, mi.separator, mi.last2, mi.issued_at
  from public.membership_ids mi
  where mi.member_id = p_member_id and mi.revoked_at is null;
end;
$$;

comment on function app.get_member_membership_id(uuid) is
  'M9b2a / owner decision D5: the member''s current membership ID in full, for the owner and holders of membership.issue_ids only. Everyone else uses app.community_membership_id_summary (masked).';


-- ══ 6. Validation ════════════════════════════════════════════════════════════

drop function if exists app.validate_membership_id(uuid, bytea, bytea);

create or replace function app.validate_membership_id(
  p_collection_id uuid,
  p_membership_id text,
  p_ip_hash       bytea
)
returns table (valid boolean, access_token text, expires_at timestamptz)
language plpgsql
volatile
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_now        timestamptz := now();
  v_canonical  text;
  v_collection record;
  v_mi         public.membership_ids%rowtype;
  v_member     public.members%rowtype;
  v_outcome    text;
  v_token      text;
  v_expires    timestamptz;
  v_limited_scope text;
begin
  if p_ip_hash is null or octet_length(p_ip_hash) <> 32 then
    raise exception 'INVALID_INPUT: ip hash' using errcode = '22023';
  end if;
  -- Overlong input is treated as an unknown ID (and still counted), never echoed.
  v_canonical := case when char_length(coalesce(p_membership_id, '')) between 1 and 40
                      then app.canonical_membership_id(p_membership_id) end;

  select c.id, c.community_id, c.status, c.audience_mode, com.status as community_status
    into v_collection
  from public.collections c
  join public.communities com on com.id = c.community_id
  where c.id = p_collection_id;

  -- Rate limits first, before any lookup, so a limited caller learns nothing.
  if (select count(*) from public.membership_validation_attempts a
        where a.ip_hash = p_ip_hash and a.attempted_at > v_now - interval '15 minutes'
          and a.outcome <> 'success') >= 10
     or (select count(*) from public.membership_validation_attempts a
        where a.ip_hash = p_ip_hash and a.attempted_at > v_now - interval '15 minutes') >= 30 then
    v_outcome := 'rate_limited';
    v_limited_scope := 'ip';
  elsif v_collection.id is not null and (select count(*) from public.membership_validation_attempts a
        where a.collection_id = v_collection.id and a.attempted_at > v_now - interval '1 hour'
          and a.outcome not in ('success', 'rate_limited')) >= 200 then
    v_outcome := 'rate_limited';
    v_limited_scope := 'collection';
  elsif v_collection.id is not null and (select count(*) from public.membership_validation_attempts a
        where a.community_id = v_collection.community_id and a.attempted_at > v_now - interval '24 hours'
          and a.outcome not in ('success', 'rate_limited')) >= 1000 then
    v_outcome := 'rate_limited';
    v_limited_scope := 'community';
  elsif v_collection.id is null or v_collection.community_status <> 'active'
        or v_collection.status <> 'active' or v_collection.audience_mode = 'public' then
    v_outcome := 'collection_unavailable';
  elsif v_canonical is null or v_canonical = '' then
    v_outcome := 'unknown_id';
  else
    select * into v_mi from public.membership_ids mi
    where mi.community_id = v_collection.community_id and mi.canonical_id = v_canonical and mi.revoked_at is null;
    if v_mi.id is null then
      v_outcome := 'unknown_id';
    else
      select * into v_member from public.members where id = v_mi.member_id;
      if not app.member_in_good_standing(v_member.status) then
        v_outcome := 'member_ineligible';
      elsif not exists (select 1 from app.resolve_collection_audience(v_collection.id) a where a.member_id = v_member.id) then
        v_outcome := 'not_in_audience';
      else
        v_outcome := 'success';
      end if;
    end if;
  end if;

  insert into public.membership_validation_attempts (ip_hash, community_id, collection_id, outcome)
  values (p_ip_hash, v_collection.community_id, v_collection.id, v_outcome);

  if v_limited_scope in ('collection', 'community') and not exists (
    select 1 from public.audit_logs l
    where l.action = 'membership.validation_lockout' and l.object_id = v_collection.id
      and l.created_at > v_now - interval '1 hour'
  ) then
    perform app.write_audit_log(
      v_collection.community_id, 'system', null, 'membership.validation_lockout', 'collection', v_collection.id,
      null, jsonb_build_object('scope', v_limited_scope)
    );
  end if;

  if v_outcome = 'success' then
    v_token := encode(extensions.gen_random_bytes(32), 'hex');
    v_expires := v_now + interval '30 minutes';
    insert into public.membership_access_grants
      (token_hash, membership_id_id, member_id, collection_id, community_id, created_at, expires_at)
    values
      (extensions.digest(v_token, 'sha256'), v_mi.id, v_member.id, v_collection.id, v_collection.community_id,
       v_now, v_expires);
    return query select true, v_token, v_expires;
  else
    return query select false, null::text, null::timestamptz;
  end if;
end;
$$;

comment on function app.validate_membership_id(uuid, text, bytea) is
  'F6 / M9b2a. Checks a typed membership ID (canonicalised here, compared with canonical_id) for one collection. Rate-limited per keyed IP hash (10 failures or 30 attempts / 15 min), per collection (200 failures / hour) and per community (1,000 failures / day). Every failure answers the same (valid = false). On success returns a 30-minute access token once (only its SHA-256 is stored). Never returns a name, code, contact or the ID.';


-- ══ 7. One-time backfill (removed by 20261123120100) ═════════════════════════

create or replace function app.backfill_membership_id_plaintext(p_row_id uuid, p_membership_id text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.membership_ids%rowtype;
begin
  select * into v_row from public.membership_ids where id = p_row_id for update;
  if v_row.id is null then
    raise exception 'NOT_FOUND: membership ID row' using errcode = 'P0002';
  end if;
  if v_row.revoked_at is not null or v_row.membership_id is not null or v_row.id_ciphertext is null then
    raise exception 'NOT_BACKFILLABLE: only a live legacy row with a ciphertext and no plaintext' using errcode = 'P0001';
  end if;
  -- The plaintext must agree with what the row already says about itself.
  if p_membership_id is null
     or left(p_membership_id, char_length(v_row.prefix) + 1) <> v_row.prefix || v_row.separator
     or right(p_membership_id, 2) <> v_row.last2 then
    raise exception 'MISMATCH: the supplied ID does not agree with the row''s prefix, separator or last two characters' using errcode = 'P0001';
  end if;

  perform set_config('app.membership_id_backfill', 'on', true);
  update public.membership_ids
  set membership_id = p_membership_id, canonical_id = app.canonical_membership_id(p_membership_id)
  where id = p_row_id;
  perform set_config('app.membership_id_backfill', 'off', true);

  -- Masked form only (no plaintext in audit rows).
  perform app.write_audit_log(
    v_row.community_id, 'system', null, 'membership.backfill_plaintext', 'member', v_row.member_id,
    null, jsonb_build_object('membership_id_id', v_row.id, 'masked', v_row.prefix || v_row.separator || '…' || v_row.last2)
  );
end;
$$;

comment on function app.backfill_membership_id_plaintext(uuid, text) is
  'M9b2a one-time backfill: gives one live legacy row its recovered plaintext ID. Not granted to any client role; run by the table owner from scripts/itest/membership-id-plaintext-backfill.mjs. Dropped by 20261123120100.';


-- ══ 8. Grants ════════════════════════════════════════════════════════════════

revoke all on function app.backfill_membership_id_plaintext(uuid, text)       from public, anon, authenticated;
revoke all on function app.issue_membership_id(uuid, text, bytea)              from public, anon;
revoke all on function app.rotate_membership_id(uuid, text, text, bytea)       from public, anon;
revoke all on function app.get_member_membership_id(uuid)                      from public, anon;
revoke all on function app.validate_membership_id(uuid, text, bytea)           from public;

grant execute on function app.issue_membership_id(uuid, text, bytea)           to authenticated;
grant execute on function app.rotate_membership_id(uuid, text, text, bytea)    to authenticated;
grant execute on function app.get_member_membership_id(uuid)                   to authenticated;
-- Anonymous: a contributor has no account. Reached only through the web
-- server's direct connection (PostgREST serves `public` only).
grant execute on function app.validate_membership_id(uuid, text, bytea)        to anon, authenticated;
